130:   const rng = new Random(seed + room * 7247);
131:   const pool = CARDS.filter(
132:     (c) =>
133:       !ids.includes(c.id) &&
134:       (!content.cards.find(row => row.id === c.id)!.requires || ids.includes(content.cards.find(row => row.id === c.id)!.requires!)),
135:   );
136:   const counts = buildCounts(ids);
137:   const preferred = rng.shuffle(pool.filter((c) => counts[c.element] > 0));
138:   const rest = rng.shuffle(pool);
139:   const bridges = rng.shuffle(
140:     pool.filter((c) =>
141:       SYNERGIES.some(
142:         (s) =>
143:           s.requires.some((id) => id === c.id) &&
144:           s.requires.some((id) => ids.includes(id)),
145:       ),
146:     ),
147:   );
148:   const results = bridges.slice(0, 1);
149:   for (const c of preferred)
150:     if (results.length < 2 && !results.includes(c)) results.push(c);
151:   for (const c of rest)
152:     if (results.length < 3 && !results.includes(c)) results.push(c);
153:   if (elite && !results.some((c) => c.rarity !== 'common')) {
154:     const rare = rest.find((c) => c.rarity !== 'common');
155:     if (rare) results[0] = rare;
